mapper.select:
SELECT 
FROM iterations iteration LEFT JOIN stories story ON story.iteration_id = iteration.id
WHERE iteration.workspace_id = #{workspaceId} AND iteration.id = #{iterationId}

mapper.update:
UPDATE iterations SET lifecycle = 'active', branch_name = #{branchName},
  provisioning_failure_summary = NULL, version = version + 1, updated_at = #{timestamp}
WHERE workspace_id = #{workspaceId} AND id = #{iterationId}
  AND lifecycle = 'provisioning' AND version = #{expectedVersion}
  AND base_commit_sha = #{baseCommitSha}

UPDATE iterations SET lifecycle = 'provisioning_failed',
  provisioning_failure_summary = #{reason}, version = version + 1, updated_at = #{timestamp}
WHERE workspace_id = #{workspaceId} AND id = #{iterationId}
  AND lifecycle = 'provisioning' AND version = #{expectedVersion}

UPDATE iterations
SET version = version + 1, updated_at = #{timestamp}
  , lifecycle = #{newLifecycle}
  , loop = #{newLoop}
  , stage = #{newStage}
WHERE workspace_id = #{workspaceId} AND id = #{iterationId}
  AND lifecycle = 'active' AND loop = #{loop} AND version = #{expectedVersion}
  AND stage IN
  #{stage}

mapper.select:
SELECT 
FROM kickoff_proposals proposal LEFT JOIN kickoff_decisions decision ON decision.proposal_id = proposal.id
WHERE proposal.iteration_id = #{iterationId} AND proposal.id = #{proposalId}

mapper.update:
UPDATE stories SET latest_revision_id = #{revisionId}, version = version + 1, updated_at = #{timestamp}
WHERE workspace_id = #{workspaceId} AND id = #{storyId} AND version = #{expectedVersion}
AND latest_revision_id IS NULL
AND latest_revision_id = #{expectedRevisionId}

mapper.select:
SELECT  FROM stories story
JOIN iterations iteration ON iteration.id = story.iteration_id
JOIN story_revisions latest ON latest.id = story.latest_revision_id
WHERE story.workspace_id = #{workspaceId}
ORDER BY story.updated_at DESC LIMIT #{size} OFFSET #{from}

SELECT  FROM story_revisions revision
JOIN stories story ON story.id = revision.story_id
WHERE story.workspace_id = #{workspaceId} AND story.id = #{storyId} AND revision.id = #{revisionId}

SELECT  FROM story_revisions revision
JOIN stories story ON story.id = revision.story_id
WHERE story.workspace_id = #{workspaceId} AND story.id = #{storyId}
ORDER BY revision.revision_number DESC LIMIT #{size} OFFSET #{from}

SELECT  FROM story_revisions revision
WHERE revision.story_id = #{storyId}
ORDER BY revision.revision_number DESC LIMIT #{size} OFFSET #{from}

mapper.update:
UPDATE story_clarifications SET status = 'answered', answer = #{answer},
  answered_by_user_id = #{answeredByUserId}, answered_at = #{answeredAt}, content_sha256 = #{contentSha256}
WHERE id = #{id} AND status = 'pending'

UPDATE story_clarifications SET status = 'waived', waived_reason = #{reason},
  waived_by_user_id = #{waivedByUserId}, waived_at = #{waivedAt}
WHERE iteration_id = #{iterationId} AND status = 'pending'

mapper.select:
SELECT  FROM scenario_set_proposals proposal
LEFT JOIN understanding_decisions decision ON decision.proposal_id = proposal.id
WHERE proposal.workspace_id = #{workspaceId} AND proposal.iteration_id = #{iterationId}
  AND proposal.id = #{proposalId}

SELECT COUNT(*) FROM story_scenarios scenario
JOIN story_revisions revision ON revision.id = scenario.story_revision_id
WHERE revision.story_id = #{storyId}

SELECT  FROM no_model_impact_decisions
WHERE workspace_id = #{workspaceId} AND iteration_id = #{iterationId}
  AND story_revision_id = #{storyRevisionId} ORDER BY decided_at DESC LIMIT 1

SELECT  FROM tasking_candidates candidate
LEFT JOIN desk_check_decisions decision ON decision.candidate_id = candidate.id
WHERE candidate.workspace_id = #{workspaceId} AND candidate.iteration_id = #{iterationId}
  AND candidate.id = #{candidateId}
